<?php
declare(strict_types=1);
/** Diagnostico somente leitura. Nunca autoriza ou executa estorno/compensacao. */
final class GFRefundReviewQA
{
    public static function review(PDO $db,int $actor,int $order,mixed $requested=null):array
    {
        $owned=false;$phase='GUARD';try{
            GFDirectBilling::guard($db);if($db->inTransaction())throw new LogicException('FIN_REFUND_REVIEW_OWNS_TRANSACTION_REQUIRED');if($order<1)throw new DomainException('pedido_invalido',422);if($db->query('SELECT @@tx_isolation')->fetchColumn()!=='REPEATABLE-READ')throw new LogicException('FIN_REFUND_REVIEW_REPEATABLE_READ_REQUIRED');
            $db->exec('START TRANSACTION READ ONLY, WITH CONSISTENT SNAPSHOT');$owned=true;$phase='AUTHORIZE';$q=$db->prepare('SELECT tipo,ativo FROM usuarios WHERE id=?');$q->execute([$actor]);$u=$q->fetch(PDO::FETCH_ASSOC);if(!$u || $u['tipo']!=='admin' || (int)$u['ativo']!==1)throw new DomainException('acesso_negado',403);
            $phase='READ_ORDER';$orders=GFReconciliation::rows($db,'SELECT * FROM pedidos WHERE id=?',[$order]);if(!$orders)throw new DomainException('pedido_nao_encontrado',404);$o=$orders[0];$payments=GFReconciliation::rows($db,'SELECT * FROM pagamentos WHERE pedido_id=?',[$order]);if(count($payments)!==1 || $o['attendance_mode']!=='TOWING' || $payments[0]['status']!=='aprovado')throw new DomainException('fluxo_ou_pagamento_fora_do_contrato');$p=$payments[0];$phase='VERIFY_FINANCIAL';$invoice=null;$jobs=[];$ledger=[];$reasons=[];
            if($p['metodo']==='dinheiro'){
                $event=GFDirectBilling::directEvidence($db,$o,$p,false);$channel='partner_cash';$amounts=['gross'=>$p['valor_total'],'received_by_partner'=>$p['valor_guincho'],'commission_due'=>$p['valor_plataforma'],'gateway_fee'=>'0.00'];$reasons[]='DIRECT_RECEIPT_REQUIRES_PARTNER_RETURN_PROOF';$evidence=[$o,$p,$event];
                if($o['fatura_id']!==null){$v=GFDirectBilling::verifyInvoice($db,(int)$o['fatura_id'],false);$f=$v['invoice'];$pays=GFReconciliation::rows($db,'SELECT * FROM faturas_pagamentos WHERE fatura_id=?',[(int)$f['id']]);$paid=$f['status']==='paga';if($paid){if(count($pays)!==1 || $pays[0]['valor']!==$v['amount'] || $pays[0]['transacao_id']!==$f['pix_transacao_id'])throw new DomainException('comprovante_da_fatura_divergente');$proof=json_decode($pays[0]['payload'],true,512,JSON_THROW_ON_ERROR);if(count($proof)!==4 || $proof[0]!== (int)$f['id'] || $proof[1]!==$v['amount'] || $proof[2]!==$pays[0]['transacao_id'])throw new DomainException('comprovante_da_fatura_divergente');}elseif($pays)throw new DomainException('comprovante_da_fatura_divergente');$invoice=['id'=>(int)$f['id'],'status'=>$f['status'],'amount'=>$v['amount'],'snapshot_must_be_preserved'=>true];$reasons[]=$paid?'COMMISSION_IN_PAID_INVOICE':'COMMISSION_IN_CLOSED_UNPAID_INVOICE';$evidence[]=[$v,$pays];}
            }elseif($p['metodo']==='mercadopago'){
                $v=GFReconciliation::online($db,(int)$p['id'],false);$channel='platform_online';$amounts=['gross'=>$v['split']['gross'],'partner_credit'=>$v['split']['partner'],'platform_credit'=>$v['split']['platform'],'gateway_fee'=>$v['split']['gateway']];$ledger=GFReconciliation::rows($db,'SELECT * FROM payout_ledger_entries WHERE pagamento_id=? ORDER BY id',[(int)$p['id']]);$jobs=GFReconciliation::rows($db,'SELECT j.id,j.status,j.attempt_count,d.state AS dispatch_state FROM payment_jobs j LEFT JOIN fin3_payout_dispatch_qa d ON d.job_id=j.id WHERE j.pagamento_id=? ORDER BY j.id',[(int)$p['id']]);$reasons[]='GATEWAY_REFUND_REQUIRES_VERIFIED_PROVIDER_RESULT';if($jobs)$reasons[]='PAYOUT_JOB_REQUIRES_RECONCILIATION';if($amounts['gateway_fee']!=='0.00')$reasons[]='GATEWAY_FEE_POLICY_REQUIRES_DEFINITION';$evidence=[$v,$ledger,$jobs];
            }else throw new DomainException('metodo_fora_do_contrato');
            $phase='VALIDATE_REQUEST';try{$amount=$requested===null?$amounts['gross']:GFMoneyInput::decimal($requested);}catch(Throwable $e){throw new DomainException('valor_solicitado_invalido',422,$e);}if(GFExactMoney::cents($amount)<1)throw new DomainException('valor_solicitado_invalido',422);if(GFExactMoney::cents($amount)>GFExactMoney::cents($amounts['gross']))throw new DomainException('valor_solicitado_supera_bruto');$partial=$amount!==$amounts['gross'];if($partial)$reasons[]='PARTIAL_REFUND_ALLOCATION_REQUIRES_DEFINITION';
            $debits=0;foreach($ledger as $entry)if($entry['entry_type']==='debito_repasse_guincho')$debits++;
            $report=['version'=>'R11BD','scope'=>'QA_ADMIN_REFUND_REVIEW_ONLY','actor_id'=>$actor,'order_id'=>$order,'payment_id'=>(int)$p['id'],'channel'=>$channel,'frozen_amounts'=>$amounts,'requested_amount'=>$amount,'partial_request'=>$partial,'invoice'=>$invoice,'observed_payout_jobs'=>$jobs,'observed_payout_debits'=>$debits,'review_reasons'=>$reasons,'source_sha256'=>hash('sha256',json_encode($evidence,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES)),'actions'=>['refund_authorized'=>false,'refund_executed'=>false,'invoice_rewrite_allowed'=>false,'compensation_authorized'=>false,'external_transport'=>false],'remaining_percent'=>30];$report['evidence_sha256']=hash('sha256',json_encode($report,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES));$db->commit();$owned=false;return ['ok'=>true,'http'=>200,'report'=>$report];
        }catch(Throwable $e){if($owned && $db->inTransaction())$db->rollBack();$http=$e instanceof DomainException && in_array($e->getCode(),[403,404,422],true)?$e->getCode():($e instanceof DomainException?409:500);$d=['project'=>'GuinchaFacil','class'=>self::class,'function'=>'review','component'=>'refund_review','phase'=>$phase,'status'=>$http===500?'FAIL':'REJECTED','error'=>$e->getMessage(),'file'=>basename($e->getFile()),'line'=>$e->getLine(),'exception'=>$e::class,'sqlstate'=>$e instanceof PDOException?($e->errorInfo[0]??null):null,'driver_code'=>$e instanceof PDOException?($e->errorInfo[1]??null):null,'remaining_percent'=>30];error_log(json_encode($d,JSON_THROW_ON_ERROR));return ['ok'=>false,'http'=>$http,'erro'=>$http===500?'triagem_indisponivel':$e->getMessage(),'diagnostic'=>$d];}
    }
}
